import { Controller, createParamDecorator, ExecutionContext, Get, Module } from "@nestjs/common"

type Page = { page: number; limit: number; skip: number }

const Pagination = createParamDecorator((maxLimit: number = 50, ctx: ExecutionContext): Page => {
    const q = ctx.switchToHttp().getRequest().query
    const page = Math.max(1, parseInt(q.page) || 1)
    const limit = Math.min(maxLimit, Math.max(1, parseInt(q.limit) || 10))
    return { page, limit, skip: (page - 1) * limit }
})

@Controller("products")
class ProductsController {
    @Get() list(@Pagination(20) p: Page) { return p }
