import { BadRequestException, Controller, createParamDecorator, ExecutionContext, Get, Module } from "@nestjs/common"

const Sort = createParamDecorator((allowed: string[], ctx: ExecutionContext) => {
    const raw = String(ctx.switchToHttp().getRequest().query.sort ?? "")
    if (!raw) return {}
    return Object.fromEntries(raw.split(",").map(part => {
        const field = part.replace(/^-/, "")
        if (!allowed.includes(field)) throw new BadRequestException(`"${field}" bo'yicha saralab bo'lmaydi`)
        return [field, part.startsWith("-") ? "DESC" : "ASC"]
    }))
})

@Controller("products")
class ProductsController { @Get() list(@Sort(["price", "name", "createdAt"]) sort: Record<string, "ASC" | "DESC">) { return { order: sort } } }
@Module({ controllers: [ProductsController] }) class AppModule {}

