import { createParamDecorator, ExecutionContext } from "@nestjs/common"

// Qaysi transport bo'lishidan qat'i nazar "user"ni topadi
export const CurrentUser = createParamDecorator((_: unknown, ctx: ExecutionContext) => {
    switch (ctx.getType()) {
        case "http": return ctx.switchToHttp().getRequest().user
        case "ws": return ctx.switchToWs().getClient().data?.user
        case "rpc": return ctx.switchToRpc().getData()?.user
        default: return undefined
    }
})

// Tekshirish: dekorator saqlagan factory'ni metadata'dan olib, soxta kontekstlar bilan chaqiramiz
const fake = (type: string, holder: object) => ({
    getType: () => type,
    switchToHttp: () => ({ getRequest: () => holder }),
    switchToWs: () => ({ getClient: () => holder }),
    switchToRpc: () => ({ getData: () => holder }),
}) as unknown as ExecutionContext

class Probe { m(@CurrentUser() _u: unknown) {} }
const meta = Reflect.getMetadata("__routeArguments__", Probe, "m")
const fn = (Object.values(meta)[0] as { factory: (d: unknown, c: ExecutionContext) => unknown }).factory
console.log("http:", fn(undefined, fake("http", { user: { id: 1 } })))
console.log("ws:  ", fn(undefined, fake("ws", { data: { user: { id: 2 } } })))
console.log("rpc: ", fn(undefined, fake("rpc", { user: { id: 3 } })))

examples.output:
http: { id: 1 }
ws:   { id: 2 }
rpc:  { id: 3 }

