import { BadRequestException, Controller, createParamDecorator, ExecutionContext, Get, Module } from "@nestjs/common"

type Opts = { name: string; min?: number; max?: number; default?: number }
const NumQuery = createParamDecorator((o: Opts, ctx: ExecutionContext) => {
    const raw = ctx.switchToHttp().getRequest().query[o.name]
    if (raw === undefined) return o.default
    const n = Number(raw)
    if (Number.isNaN(n) || (o.min !== undefined && n < o.min) || (o.max !== undefined && n > o.max))
        throw new BadRequestException(`${o.name} ${o.min ?? "-∞"}..${o.max ?? "∞"} oralig'ida son bo'lsin`)
    return n
})

@Controller("list")
class ListController {
    @Get() list(@NumQuery({ name: "page", min: 1, default: 1 }) page: number, @NumQuery({ name: "size", min: 1, max: 50, default: 10 }) size: number) { return { page, size } }
}
@Module({ controllers: [ListController] }) class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/list")
    await http.get("/list?page=3&size=25")
    await http.get("/list?size=100")
    await http.close()
}
main()

