import { Controller, createParamDecorator, ExecutionContext, Get, Module } from "@nestjs/common"

const AcceptLanguages = createParamDecorator((_: unknown, ctx: ExecutionContext) => {
    const header: string = ctx.switchToHttp().getRequest().headers["accept-language"] ?? ""
    return header.split(",")
        .map(part => { const [tag, q] = part.trim().split(";q="); return { tag, q: q ? Number(q) : 1 } })
        .filter(x => x.tag)
        .sort((a, b) => b.q - a.q)
        .map(x => x.tag)
})
