import { CanActivate, Controller, ExecutionContext, Get, Injectable, Module, NotFoundException } from "@nestjs/common"
import { APP_GUARD, Reflector } from "@nestjs/core"

const Feature = Reflector.createDecorator<string>()

@Injectable()
class FeatureFlags { enabled = new Set(["dark-mode"]) }

@Injectable()
class FeatureGuard implements CanActivate {
    constructor(private readonly r: Reflector, private readonly flags: FeatureFlags) {}
    canActivate(ctx: ExecutionContext) {
        const feature = this.r.get(Feature, ctx.getHandler())
        if (feature && !this.flags.enabled.has(feature)) throw new NotFoundException()
        return true
    }
}

@Controller()
class AppController {
    @Get("theme") @Feature("dark-mode") theme() { return "qorong'i rejim" }
    @Get("checkout") @Feature("new-checkout") checkout() { return "yangi to'lov oynasi" }
}

@Module({ controllers: [AppController], providers: [FeatureFlags, { provide: APP_GUARD, useClass: FeatureGuard }] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
