import { CanActivate, Controller, ExecutionContext, Get, HttpException, Injectable, Module, UseGuards } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

type Limit = { max: number; per: string }
const RateLimit = Reflector.createDecorator<Limit>()

@Injectable()
class RateLimitGuard implements CanActivate {
    private counters = new Map<string, number>()
    constructor(private readonly r: Reflector) {}
    canActivate(ctx: ExecutionContext) {
        const limit = this.r.get(RateLimit, ctx.getHandler())
        if (!limit) return true
        const key = ctx.getHandler().name
        const count = (this.counters.get(key) ?? 0) + 1
        this.counters.set(key, count)
        if (count > limit.max) throw new HttpException(`Limit: ${limit.max} ta so'rov / ${limit.per}`, 429)
        return true
    }
}

