import { Controller, Get, Module, SetMetadata } from "@nestjs/common"
import { Reflector } from "@nestjs/core"

function Wrap(): MethodDecorator {
    return (_t, _k, descriptor: PropertyDescriptor) => {
        const original = descriptor.value
        descriptor.value = function (...args: unknown[]) { return original.apply(this, args) }
        // metadata eski funksiyada qolgan — yangisiga ko'chiramiz
        for (const key of Reflect.getMetadataKeys(original)) Reflect.defineMetadata(key, Reflect.getMetadata(key, original), descriptor.value)
    }
}

