import { Injectable, Module, OnModuleInit, SetMetadata } from "@nestjs/common"
import { DiscoveryModule, DiscoveryService, MetadataScanner, NestFactory, Reflector } from "@nestjs/core"

const COMMAND = "COMMAND"
const Command = (name: string) => SetMetadata(COMMAND, name)

@Injectable() class UserCommands { @Command("user:list") list() { return "foydalanuvchilar" } @Command("user:ban") ban() { return "bloklandi" } }
@Injectable() class CacheCommands { @Command("cache:clear") clear() { return "kesh tozalandi" } }

@Injectable()
class CommandRegistry implements OnModuleInit {
    commands = new Map<string, () => unknown>()
    constructor(private readonly discovery: DiscoveryService, private readonly scanner: MetadataScanner, private readonly reflector: Reflector) {}
    onModuleInit() {
        for (const wrapper of this.discovery.getProviders()) {
            const instance = wrapper.instance
            if (!instance || typeof instance !== "object") continue
            for (const method of this.scanner.getAllMethodNames(Object.getPrototypeOf(instance))) {
                const name = this.reflector.get<string>(COMMAND, instance[method])
                if (name) this.commands.set(name, () => instance[method]())
            }
        }
    }
}

@Module({ imports: [DiscoveryModule], providers: [UserCommands, CacheCommands, CommandRegistry] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.init()
    const reg = app.get(CommandRegistry)
    console.log("topilgan buyruqlar:", [...reg.commands.keys()].sort())
    console.log("cache:clear →", reg.commands.get("cache:clear")!())
    await app.close()
}
main()

