const CACHE_TTL = "cacheTtl"
@Injectable() class SimpleCache implements NestInterceptor {
    private store = new Map<string, { value: unknown; until: number }>()
    constructor(private reflector: Reflector) {}
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const ttl = this.reflector.get<number>(CACHE_TTL, ctx.getHandler())
        const key = ctx.switchToHttp().getRequest().url
        const hit = this.store.get(key)
        if (hit && hit.until > Date.now()) return of(hit.value)
        return next.handle().pipe(tap(value => this.store.set(key, { value, until: Date.now() + ttl * 1000 })))
    }
}
const Cached = (ttlSeconds: number) => applyDecorators(SetMetadata(CACHE_TTL, ttlSeconds), UseInterceptors(SimpleCache))
