import { Controller, Injectable, Module, Post } from "@nestjs/common"

function Retry(times: number) {
    return (_target: object, key: string | symbol, descriptor: PropertyDescriptor) => {
        const original = descriptor.value
        descriptor.value = async function (this: unknown, ...args: unknown[]) {
            for (let i = 1; ; i++) {
                try { return await original.apply(this, args) } catch (e) {
                    console.log(`  ${String(key)}: ${i}-urinish xato (${(e as Error).message})`)
                    if (i >= times) throw e
                }
            }
        }
    }
}
@Injectable() class SmsService {
    attempts = 0
    @Retry(3) async send(to: string) {
        if (++this.attempts < 3) throw new Error("tarmoq uzildi")
        return `SMS ${to} ga yuborildi`
    }
}
