import { Controller, Get, Injectable, Module } from "@nestjs/common"

function LogCalls<T extends new (...args: any[]) => object>(ctor: T) {
    for (const key of Object.getOwnPropertyNames(ctor.prototype)) {
        const original = ctor.prototype[key]
        if (key === "constructor" || typeof original !== "function") continue
        ctor.prototype[key] = function (this: unknown, ...args: unknown[]) {
            console.log(`→ ${ctor.name}.${key}(${args.map(a => JSON.stringify(a)).join(", ")})`)
            return original.apply(this, args)
        }
    }
}
