import { BadRequestException, Body, Controller, Injectable, Module, Post } from "@nestjs/common"

function NonNegativeArgs(_target: object, key: string | symbol, descriptor: PropertyDescriptor) {
    const original = descriptor.value
    descriptor.value = function (this: unknown, ...args: unknown[]) {
        args.forEach((a, i) => {
            if (typeof a === "number" && a < 0) throw new BadRequestException(`${String(key)}: ${i + 1}-argument manfiy (${a})`)
        })
        return original.apply(this, args)
    }
}
