const PAGE_SIZE = "pageSize"
@Injectable() class PaginateInterceptor implements NestInterceptor {
    constructor(private reflector: Reflector) {}
    intercept(ctx: ExecutionContext, next: CallHandler) {
        const size = this.reflector.get<number>(PAGE_SIZE, ctx.getHandler())
        const page = Number(ctx.switchToHttp().getRequest().query.page ?? 1)
        return next.handle().pipe(map((all: unknown[]) => ({ page, total: all.length, items: all.slice((page - 1) * size, page * size) })))
    }
}
