import { CanActivate, Controller, ExecutionContext, Module, Param, Patch, UseGuards } from "@nestjs/common"

function AnyOf(...guards: (new () => CanActivate)[]) {
    class AnyOfGuard implements CanActivate {
        async canActivate(ctx: ExecutionContext) {
            for (const G of guards) if (await new G().canActivate(ctx)) return true
            return false
        }
    }
    return UseGuards(new AnyOfGuard())
}
class IsAdmin implements CanActivate {
    canActivate(ctx: ExecutionContext) { return ctx.switchToHttp().getRequest().headers["x-role"] === "admin" }
}
class IsOwner implements CanActivate {
    canActivate(ctx: ExecutionContext) { const req = ctx.switchToHttp().getRequest(); return req.headers["x-user-id"] === req.params.id }
}
@Controller("profiles") class P { @Patch(":id") @AnyOf(IsAdmin, IsOwner) upd(@Param("id") id: string) { return { updated: id } } }
@Module({ controllers: [P] }) class AppModule {}

