const Job = DiscoveryService.createDecorator<string>()
@Injectable() @Job("0 * * * *") class CleanupJob { run() { return "tozalandi" } }
@Injectable() @Job("*/5 * * * *") class ReportJob { run() { return "hisobot tayyor" } }
@Injectable() class PlainService {}
@Injectable() class Scheduler implements OnModuleInit {
    constructor(private discovery: DiscoveryService) {}
    onModuleInit() {
        for (const w of this.discovery.getProviders({ metadataKey: Job.KEY })) {
            const cron = this.discovery.getMetadataByDecorator(Job, w)
            console.log(`${w.name} [${cron}] → ${(w.instance as { run(): string }).run()}`)
        }
    }
}
@Module({ imports: [DiscoveryModule], providers: [CleanupJob, ReportJob, PlainService, Scheduler] }) class AppModule {}

async function main() {
    const app = await NestFactory.createApplicationContext(AppModule, { logger: false })
    await app.close()
}
